-- PostgreSQL production schema. IDs are externally assigned and immutable.
CREATE TABLE customers (customer_id VARCHAR(16) PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, consent_status VARCHAR(12) NOT NULL CHECK (consent_status IN ('granted','denied','unknown')), lifecycle_state VARCHAR(16) NOT NULL CHECK (lifecycle_state IN ('active','inactive','deleted')), country CHAR(2));
CREATE TABLE pages (page_id VARCHAR(16) PRIMARY KEY, page_name TEXT NOT NULL, page_type VARCHAR(24) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE products (product_id VARCHAR(16) PRIMARY KEY, product_name TEXT NOT NULL, category TEXT NOT NULL, unit_price NUMERIC(12,2) NOT NULL CHECK (unit_price >= 0), is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE experiments (experiment_id VARCHAR(16) PRIMARY KEY, name TEXT NOT NULL, status VARCHAR(16) NOT NULL CHECK (status IN ('draft','active','completed','paused')), start_at TIMESTAMPTZ NOT NULL, end_at TIMESTAMPTZ NOT NULL CHECK (end_at >= start_at));
CREATE TABLE sessions (session_id VARCHAR(20) PRIMARY KEY, customer_id VARCHAR(16) REFERENCES customers(customer_id), anonymous_id VARCHAR(24) NOT NULL, started_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ, channel VARCHAR(16) NOT NULL CHECK (channel IN ('website','mobile_app')), device_type VARCHAR(16) NOT NULL CHECK (device_type IN ('desktop','mobile','tablet')), consent_status VARCHAR(12) NOT NULL CHECK (consent_status IN ('granted','denied','unknown')), is_bot BOOLEAN NOT NULL DEFAULT FALSE, lifecycle_state VARCHAR(16) NOT NULL CHECK (lifecycle_state IN ('active','completed','expired')), CHECK (ended_at IS NULL OR ended_at >= started_at));
CREATE TABLE journey_events (event_id VARCHAR(64) PRIMARY KEY, session_id VARCHAR(20) NOT NULL REFERENCES sessions(session_id), customer_id VARCHAR(16) REFERENCES customers(customer_id), anonymous_id VARCHAR(24) NOT NULL, event_type VARCHAR(40) NOT NULL, event_timestamp TIMESTAMPTZ NOT NULL, ingestion_timestamp TIMESTAMPTZ NOT NULL, channel VARCHAR(16) NOT NULL CHECK (channel IN ('website','mobile_app')), page_id VARCHAR(16) REFERENCES pages(page_id), product_id VARCHAR(16) REFERENCES products(product_id), event_properties JSONB NOT NULL DEFAULT '{}', event_version VARCHAR(12) NOT NULL, CHECK (ingestion_timestamp >= event_timestamp));
CREATE INDEX journey_events_session_time_idx ON journey_events(session_id,event_timestamp);
CREATE INDEX journey_events_ingestion_idx ON journey_events(ingestion_timestamp);
CREATE TABLE carts (cart_id VARCHAR(20) PRIMARY KEY, session_id VARCHAR(20) NOT NULL REFERENCES sessions(session_id), customer_id VARCHAR(16) REFERENCES customers(customer_id), created_at TIMESTAMPTZ NOT NULL, state VARCHAR(16) NOT NULL CHECK (state IN ('open','abandoned','converted','expired')));
CREATE TABLE cart_items (cart_item_id VARCHAR(20) PRIMARY KEY, cart_id VARCHAR(20) NOT NULL REFERENCES carts(cart_id), product_id VARCHAR(16) NOT NULL REFERENCES products(product_id), quantity INTEGER NOT NULL CHECK (quantity > 0), unit_price NUMERIC(12,2) NOT NULL CHECK (unit_price >= 0), UNIQUE(cart_id,product_id));
CREATE TABLE orders (order_id VARCHAR(20) PRIMARY KEY, session_id VARCHAR(20) NOT NULL REFERENCES sessions(session_id), customer_id VARCHAR(16) REFERENCES customers(customer_id), cart_id VARCHAR(20) REFERENCES carts(cart_id), ordered_at TIMESTAMPTZ NOT NULL, status VARCHAR(16) NOT NULL CHECK (status IN ('pending','paid','failed','refunded')), total_amount NUMERIC(12,2) NOT NULL CHECK (total_amount >= 0), currency CHAR(3) NOT NULL);
CREATE TABLE support_tickets (ticket_id VARCHAR(20) PRIMARY KEY, session_id VARCHAR(20) NOT NULL REFERENCES sessions(session_id), customer_id VARCHAR(16) REFERENCES customers(customer_id), created_at TIMESTAMPTZ NOT NULL, status VARCHAR(16) NOT NULL CHECK (status IN ('open','pending','resolved','closed')), reason TEXT NOT NULL);
CREATE TABLE experiment_assignments (assignment_id VARCHAR(20) PRIMARY KEY, experiment_id VARCHAR(16) NOT NULL REFERENCES experiments(experiment_id), session_id VARCHAR(20) NOT NULL REFERENCES sessions(session_id), variant VARCHAR(32) NOT NULL, assigned_at TIMESTAMPTZ NOT NULL, UNIQUE(experiment_id,session_id));
CREATE TABLE journey_outcomes (outcome_id VARCHAR(32) PRIMARY KEY, session_id VARCHAR(20) NOT NULL UNIQUE REFERENCES sessions(session_id), outcome_type VARCHAR(32) NOT NULL CHECK (outcome_type IN ('converted','checkout_abandoned','cart_abandoned','browsed','bot')), outcome_at TIMESTAMPTZ NOT NULL, rule_version VARCHAR(12) NOT NULL);
